<?php
$e = static fn($value): string => htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8');
?>
<section class="page-hero page-hero-compact"><div><p class="eyebrow">Back Office · <?= $e($plantation['username']) ?></p><h1><?= $e($plantation['nom']) ?></h1><p><?= $e($plantation['varieteNom'] ?: 'Variété non précisée') ?></p></div><div class="form-actions"><a class="button button-light" href="index.php?action=admin_plantations">Retour à la liste</a><form method="post" action="index.php?action=admin_plantation_delete" data-confirm="Supprimer cette plantation et tous ses suivis ?"><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="id" value="<?= (int) $plantation['idPlantation'] ?>"><button class="button button-danger" type="submit">Supprimer</button></form></div></section>
<section class="form-panel"><div class="detail-grid"><div><span>Adresse</span><strong><?= $e($plantation['adresse']) ?></strong></div><div><span>Surface</span><strong><?= $e($plantation['surface']) ?> m²</strong></div><div><span>Support</span><strong><?= $e($plantation['typeSupport']) ?></strong></div><div><span>Date</span><strong><?= $e($plantation['dateCreation']) ?></strong></div><div><span>Latitude</span><strong><?= $e($plantation['latitude'] ?? '—') ?></strong></div><div><span>Longitude</span><strong><?= $e($plantation['longitude'] ?? '—') ?></strong></div></div></section>
<section class="followup-section"><h2 class="section-title">Suivis associés</h2><div class="history-list"><?php foreach ($suivis as $s): ?><article class="history-entry"><h3><?= $e($s['dateSuivi']) ?> · <?= $e($s['etat']) ?></h3><?php if ($s['arrosage'] !== ''): ?><p><strong>Arrosage :</strong> <?= $e($s['arrosage']) ?></p><?php endif; ?><?php if ($s['observation'] !== ''): ?><p><strong>Observation :</strong> <?= nl2br($e($s['observation'])) ?></p><?php endif; ?><?php if ($s['photo'] !== ''): ?><p><strong>Photo :</strong> <?= $e($s['photo']) ?></p><?php endif; ?><?php if ($s['diagnosticIA'] !== ''): ?><p><strong>Diagnostic IA :</strong> <?= nl2br($e($s['diagnosticIA'])) ?></p><?php endif; ?></article><?php endforeach; ?><?php if (!$suivis): ?><p class="empty-state">Aucun suivi enregistré.</p><?php endif; ?></div></section>
